window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5ae260ffc63d2a7c"]={"versions": [{"id": "FIG-5ae260ffc63d2a7c", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Rollen- und Artefakt-Flussdiagramm (Modellierung von Artefakten und Entwickleraktivitäten im Integrationsprozess) im Kontext des AUTOSAR Basic Software Schedulers (SchM) innerhalb der AUTOSAR Classic Platform. Das Diagramm zeigt die Interaktion der Rolle des Integrators/Implementierers des BSW Schedulers mit Eingangs- und Ausgangsartefakten (Header, Quelltexte, Objektdateien, XML-Beschreibungen und Executables).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteur</strong>:</li>\n<li><code>Integrator (Implementor of BSW Scheduler)</code>: Rolle/Entwickler, der SchM implementiert und das Gesamtsystem baut.</li>\n<li><strong>Eingangsartefakte (Zulieferung BSW-Module)</strong>:</li>\n<li><code>&lt;ModulePrefix&gt;</code> (<code>.c</code>-Dateien, gestapelt): Quellcode des BSW-Moduls.</li>\n<li><code>&lt;ModulePrefix&gt;_cfg</code> (<code>.h</code>-Dateien): Modulspezifische Konfigurations-Header.</li>\n<li><code>&lt;ModulePrefix&gt;</code> (<code>.obj</code>): Vorkompilierte Objektdatei des BSW-Moduls.</li>\n<li><code>&lt;ModulePrefix&gt;_Description</code> (<code>.XML</code>): Modulbeschreibungsdatei.</li>\n<li><strong>SchM-Artefakte</strong>:</li>\n<li><code>SchM</code> (<code>.c</code>): Implementierung des BSW-Schedulers.</li>\n<li><code>SchM_cfg</code> (<code>.h</code>): Konfigurations-Header des SchM.</li>\n<li><code>SchM_&lt;ModulePrefix&gt;</code> (<code>.h</code>): Modulspezifischer Scheduler-Header für Standardaufrufe.</li>\n<li><code>SchM_&lt;ModulePrefix&gt;_*(optimized)</code> (<code>.h</code>): Modulspezifischer optimierter Scheduler-Header.</li>\n<li><strong>Zielartefakt</strong>:</li>\n<li><code>BasicSoftware</code> (<code>.exe</code>): Kompiliertes/gelinktes Gesamtsystem der Basissoftware.</li>\n<li><strong>Beziehungen & Stereotypen</strong>:</li>\n<li><code>«deliveredTo»</code>: Modul-Artefakte (<code>.obj</code>, <code>.XML</code>) werden an den Integrator geliefert.</li>\n<li><code>«refersTo»</code>: Integrator bzw. Executable referenziert Artefakte (<code>.obj</code>, <code>.c</code>, <code>.XML</code>).</li>\n<li><code>«implements»</code>: Integrator implementiert <code>SchM</code> (<code>.c</code>).</li>\n<li><code>«includes»</code>: <code>SchM</code> (<code>.c</code>) bindet <code>SchM_cfg</code> (<code>.h</code>) ein.</li>\n<li><code>«generates»</code>: Integrator generiert bzw. baut <code>BasicSoftware</code> (<code>.exe</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zulieferung</strong>: Der BSW-Modullieferant liefert Quellcode bzw. vorkompilierte Binaries (<code>.obj</code>), Konfigurations-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und XML-Beschreibungen (<code>&lt;ModulePrefix&gt;_Description.XML</code>) an den Integrator (<code>«deliveredTo»</code>).</li>\n<li><strong>Implementierung</strong>: Der Integrator implementiert den BSW-Scheduler (<code>SchM.c</code>) unter Bezugnahme auf die Modulbeschreibungen und BSW-Artefakte.</li>\n<li><strong>Inklusion & Schnittstellen</strong>: <code>SchM.c</code> inkludiert die Konfiguration <code>SchM_cfg.h</code>; modulspezifische Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>, optimierte Varianten) stellen die Scheduler-Schnittstellen für die BSW-Module bereit.</li>\n<li><strong>Erzeugung</strong>: Der Integrator erzeugt über Link- und Build-Schritte aus den Modulobjekten und SchM-Quellen das lauffähige Binary <code>BasicSoftware.exe</code> (<code>«generates»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild verdeutlicht die Integratorperspektive auf die BSW-Scheduler-Generierung und -Kompilierung. In frühen AUTOSAR-Releases (R2.1/R3.0) ist der SchM häufig noch manuell oder halbautomatisch durch den Integrator implementiert bzw. konfiguriert worden. Entwickler müssen sicherstellen, dass die BSW-Modul-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und SchM-Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>) konsistent eingebunden werden und XML-Beschreibungen mit den Binärartefakten (<code>.obj</code>) der Module übereinstimmen.</p>"}, {"id": "FIG-9909d30d87148705", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Rollen- und Artefakt-Flussdiagramm (Modellierung von Artefakten und Entwickleraktivitäten im Integrationsprozess) im Kontext des AUTOSAR Basic Software Schedulers (SchM) innerhalb der AUTOSAR Classic Platform. Das Diagramm zeigt die Interaktion der Rolle des Integrators/Implementierers des BSW Schedulers mit Eingangs- und Ausgangsartefakten (Header, Quelltexte, Objektdateien, XML-Beschreibungen und Executables).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteur</strong>:</li>\n<li><code>Integrator (Implementor of BSW Scheduler)</code>: Rolle/Entwickler, der SchM implementiert und das Gesamtsystem baut.</li>\n<li><strong>Eingangsartefakte (Zulieferung BSW-Module)</strong>:</li>\n<li><code>&lt;ModulePrefix&gt;</code> (<code>.c</code>-Dateien, gestapelt): Quellcode des BSW-Moduls.</li>\n<li><code>&lt;ModulePrefix&gt;_cfg</code> (<code>.h</code>-Dateien): Modulspezifische Konfigurations-Header.</li>\n<li><code>&lt;ModulePrefix&gt;</code> (<code>.obj</code>): Vorkompilierte Objektdatei des BSW-Moduls.</li>\n<li><code>&lt;ModulePrefix&gt;_Description</code> (<code>.XML</code>): Modulbeschreibungsdatei.</li>\n<li><strong>SchM-Artefakte</strong>:</li>\n<li><code>SchM</code> (<code>.c</code>): Implementierung des BSW-Schedulers.</li>\n<li><code>SchM_cfg</code> (<code>.h</code>): Konfigurations-Header des SchM.</li>\n<li><code>SchM_&lt;ModulePrefix&gt;</code> (<code>.h</code>): Modulspezifischer Scheduler-Header für Standardaufrufe.</li>\n<li><code>SchM_&lt;ModulePrefix&gt;_*(optimized)</code> (<code>.h</code>): Modulspezifischer optimierter Scheduler-Header.</li>\n<li><strong>Zielartefakt</strong>:</li>\n<li><code>BasicSoftware</code> (<code>.exe</code>): Kompiliertes/gelinktes Gesamtsystem der Basissoftware.</li>\n<li><strong>Beziehungen & Stereotypen</strong>:</li>\n<li><code>«deliveredTo»</code>: Modul-Artefakte (<code>.obj</code>, <code>.XML</code>) werden an den Integrator geliefert.</li>\n<li><code>«refersTo»</code>: Integrator bzw. Executable referenziert Artefakte (<code>.obj</code>, <code>.c</code>, <code>.XML</code>).</li>\n<li><code>«implements»</code>: Integrator implementiert <code>SchM</code> (<code>.c</code>).</li>\n<li><code>«includes»</code>: <code>SchM</code> (<code>.c</code>) bindet <code>SchM_cfg</code> (<code>.h</code>) ein.</li>\n<li><code>«generates»</code>: Integrator generiert bzw. baut <code>BasicSoftware</code> (<code>.exe</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zulieferung</strong>: Der BSW-Modullieferant liefert Quellcode bzw. vorkompilierte Binaries (<code>.obj</code>), Konfigurations-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und XML-Beschreibungen (<code>&lt;ModulePrefix&gt;_Description.XML</code>) an den Integrator (<code>«deliveredTo»</code>).</li>\n<li><strong>Implementierung</strong>: Der Integrator implementiert den BSW-Scheduler (<code>SchM.c</code>) unter Bezugnahme auf die Modulbeschreibungen und BSW-Artefakte.</li>\n<li><strong>Inklusion & Schnittstellen</strong>: <code>SchM.c</code> inkludiert die Konfiguration <code>SchM_cfg.h</code>; modulspezifische Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>, optimierte Varianten) stellen die Scheduler-Schnittstellen für die BSW-Module bereit.</li>\n<li><strong>Erzeugung</strong>: Der Integrator erzeugt über Link- und Build-Schritte aus den Modulobjekten und SchM-Quellen das lauffähige Binary <code>BasicSoftware.exe</code> (<code>«generates»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild verdeutlicht die Integratorperspektive auf die BSW-Scheduler-Generierung und -Kompilierung. In frühen AUTOSAR-Releases (R2.1/R3.0) ist der SchM häufig noch manuell oder halbautomatisch durch den Integrator implementiert bzw. konfiguriert worden. Entwickler müssen sicherstellen, dass die BSW-Modul-Header (<code>&lt;ModulePrefix&gt;_cfg.h</code>) und SchM-Header (<code>SchM_&lt;ModulePrefix&gt;.h</code>) konsistent eingebunden werden und XML-Beschreibungen mit den Binärartefakten (<code>.obj</code>) der Module übereinstimmen.</p>"}], "trans": [{"from": "FIG-5ae260ffc63d2a7c", "to": "FIG-9909d30d87148705", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
